type Todo = { id: number; text: string; completed: boolean };

interface TodoApp {
  addTodo: (text: string) => Todo;
  getTodo: (id: number) => Todo | undefined;
  toggleTodo: (id: number) => void;
  deleteTodo: (id: number) => void;
  listTodos: () => Todo[];
  listCompleted: () => Todo[];
  listPending: () => Todo[];
  clearCompleted: () => void;
}

const createTodoApp = (): TodoApp => {
  let nextId = 1;
  let todos: Todo[] = [];

  const addTodo = (text: string): Todo => {
    todos.push({ id: nextId++, text, completed: false });
    return todos[todos.length - 1];
  };

  const getTodo = (id: number): Todo | undefined => {
    return todos.find((t) => t.id === id);
  };

  const toggleTodo = (id: number): void => {
    const todo = todos.find((t) => t.id === id);
    if (todo !== undefined) {
      todo.completed = !todo.completed;
    }
  };

  const deleteTodo = (id: number): void => {
    todos = todos.filter((t) => t.id !== id);
  };

  const listTodos = (): Todo[] => [...todos];

  const listCompleted = (): Todo[] => todos.filter((t) => t.completed);

  const listPending = (): Todo[] => todos.filter((t) => !t.completed);

  const clearCompleted = (): void => {
    todos = todos.filter((t) => !t.completed);
  };

  return {
    addTodo,
    getTodo,
    toggleTodo,
    deleteTodo,
    listTodos,
    listCompleted,
    listPending,
    clearCompleted,
  };
};

export { createTodoApp };
