    return this;
  }

  clear(): Calculator {
    this.current = 0;
    return this;
  }

  result(): number {
    return this.current;
  }

  memoryStore(): Calculator {
    return new Calculator({
      current: this.memory,
      memory: this.memory
    });
  }

  memoryRecall(): number {
    return this.memory;
