class Calculator {
    private currentValue: number = 0;
    private memoryValue: number = 0;

    public add(num: number): Calculator {
        this.currentValue += num;
        return this;
    }

    public subtract(num: number): Calculator {
        this.currentValue -= num;
        return this;
    }

    public multiply(num: number): Calculator {
        this.currentValue *= num;
        return this;
    }

    public divide(num: number): Calculator {
        if (num === 0) {
            throw new Error("Cannot divide by zero");
        }
        this.currentValue /= num;
        return this;
    }

    public clear(): Calculator {
        this.currentValue = 0;
        return this;
    }

    public result(): number {
        return this.currentValue;
    }

    public memoryStore(): Calculator {
        this.memoryValue = this.currentValue;
        return this;
    }

    public memoryAdd(): Calculator {
        this.memoryValue += this.currentValue;
        return this;
    }

    public memoryClear(): Calculator {
        this.memoryValue = 0;
        return this;
    }

    public memoryRecall(): [number, number] {
        const [result, storedValue] = [this.currentValue, this.memoryValue];
        this.memoryValue = 0;
        return [result, storedValue];
    }
}

export function createCalculator(): Calculator {
    return new Calculator();
}
