export function createTodoApp() {
    type Todo = { id: number; text: string; completed: boolean };

    let nextId = 1;
    const store = new Map<number, Todo>();

    const addTodo = (text: string): Todo => {
        const todo: Todo = { id: nextId++, text, completed: false };
        store.set(todo.id, todo);
        return todo;
    };

    const getTodo = (id: number): Todo | undefined => store.get(id) ?? undefined;

    const toggleTodo = (id: number): void => {
        const todo = store.get(id);
        if (todo) {
            store.set(id, { ...todo, completed: !todo.completed });
        }
    };

    const deleteTodo = (id: number): void => {
        store.delete(id);
    };

    const listTodos = (): Todo[] => Array.from(store.values());

    const listCompleted = (): Todo[] => Array.from(store.values()).filter((t) => t.completed);

    const listPending = (): Todo[] => Array.from(store.values()).filter((t) => !t.completed);

    const clearCompleted = (): void => {
        for (const [id, todo] of store.entries()) {
            if (todo.completed) {
                store.delete(id);
            }
        }
    };

    return { addTodo, getTodo, toggleTodo, deleteTodo, listTodos, listCompleted, listPending, clearCompleted };
}
